breach.segment:
WHERE ple_n >= 5 OR grants_n >= 5
// Exclude very small tiers (< 1 GB memory): they run permanently at their memory limit.
// Remove this filter to include them.
| WHERE mem_quota IS NULL OR mem_quota >= 1000000000
// PLE floor scales with memory: 300 s per 4 GiB (never below 300 s). Tune the 300.
| EVAL ple_floor = GREATEST(300.0, 300.0 * COALESCE(mem_quota, 0) / 4294967296.0),
       ple_growth = ple_last - ple_first,
       hit_ratio_avg = ROUND(hit_ratio_avg, 2),
       grants_avg = ROUND(grants_avg, 2)
// Breach conditions (any of):
//  - grants: queries queued for workspace memory (sorts, hashes) on average
//  - ple: PLE below the floor for the whole window AND not climbing steadily
//    (a restarted instance's PLE grows ~60 s per minute; growth >= 30 s per minute is warm-up, which also covers short post-start windows)
//  - hit ratio: buffer cache hit ratio (percent 0-100) persistently low
| EVAL grants_breach = grants_n >= 5 AND grants_avg >= 1,
       ple_breach = ple_n >= 5 AND ple_max < ple_floor AND ple_growth < 30.0 * (ple_n - 1),
       hit_breach = ple_n >= 5 AND hit_ratio_avg < 90
| WHERE grants_breach OR ple_breach OR hit_breach
| EVAL reason = CASE(
    grants_breach, "memory grants pending",
    ple_breach, "page life expectancy below floor",
    "buffer cache hit ratio low")
| KEEP database_id, reason, grants_avg, ple_max, ple_floor, hit_ratio_avg, mem_quota
| SORT database_id
| LIMIT 100
